from __future__ import annotations

from dataclasses import dataclass
from typing import Callable


@dataclass
class Subscription:
    token: int
    topic: str
    callback: Callable[[dict[str, object]], None]
    once: bool = False
    active: bool = True
    _book: "SubscriptionBook | None" = None

    def close(self) -> None:
        if self.active and self._book is not None:
            self._book.remove(self.token)


class SubscriptionBook:
    def __init__(self) -> None:
        self._next_token = 1
        self._topics: dict[str, list[Subscription]] = {}

    def add(self, topic: str, callback: Callable[[dict[str, object]], None], *, once: bool = False) -> Subscription:
        subscription = Subscription(self._next_token, topic, callback, once=once, _book=self)
        self._next_token += 1
        self._topics.setdefault(topic, []).append(subscription)
        return subscription

    def remove(self, token: int) -> None:
        for subscriptions in self._topics.values():
            for subscription in subscriptions:
                if subscription.token == token:
                    subscription.active = False
                    subscriptions.remove(subscription)
                    return

    def for_topic(self, topic: str) -> list[Subscription]:
        return self._topics.get(topic, [])


