from __future__ import annotations

from .bus import EventBus
from .subscriptions import Subscription


class CounterProjection:
    def __init__(self, bus: EventBus) -> None:
        self._bus = bus
        self._subscription: Subscription | None = None
        self.total = 0

    def start(self) -> None:
        self._subscription = self._bus.subscribe("delta", self._apply)

    def stop(self) -> None:
        if self._subscription is not None:
            self._subscription.close()
            self._subscription = None

    def _apply(self, payload: dict[str, object]) -> None:
        amount = payload.get("amount")
        if not isinstance(amount, int) or isinstance(amount, bool):
            raise ValueError("amount must be an integer")
        self.total += amount
from __future__ import annotations

from .subscriptions import Subscription, SubscriptionBook


class EventBus:
    def __init__(self) -> None:
        self._subscriptions = SubscriptionBook()

    def subscribe(self, topic: str, callback, *, once: bool = False) -> Subscription:
        return self._subscriptions.add(topic, callback, once=once)

    def publish(self, topic: str, payload: dict[str, object]) -> None:
        for subscription in self._subscriptions.for_topic(topic):
            if not subscription.active:
                continue
            subscription.callback(payload)
            if subscription.once:
                subscription.close()
