import unittest

from event_ledger import CounterProjection, EventBus, EventStore


class ProjectionTests(unittest.TestCase):
    def test_starting_a_projection_twice_does_not_duplicate_updates(self):
        bus = EventBus()
        store = EventStore(bus)
        projection = CounterProjection(bus)
        projection.start()
        projection.start()

        store.append("delta", {"amount": 4})

        self.assertEqual(projection.total, 4)


